.control
* 1. DC Operating Point & Power Dissipation
op
let p_diss = -i(VDD) * 1.8
print p_diss

* 2. Transient Analysis (Fig. 24.31 step response)
tran 0.1n 600n 500n
meas tran vout_init find v(Vout) at=510n
meas tran vout_low  min v(Vout) from=520n to=550n
meas tran vout_high max v(Vout) from=560n to=590n
meas tran t_fall trig v(Vout) val=0.8 fall=1 targ v(Vout) val=0.2 fall=1
meas tran t_rise trig v(Vout) val=0.2 rise=1 targ v(Vout) val=0.8 rise=1
let sr_fall = (0.8 - 0.2) / t_fall / 1e6
let sr_rise = (0.8 - 0.2) / t_rise / 1e6
print sr_fall sr_rise

* 3. AC Analysis (Open-loop and closed-loop response)
ac dec 50 10 1G
let aol_db = vdb(Vout) - vdb(vm)
let aol_phase = 180/PI * cph(v(Vout) / (v(vp) - v(vm)))
meas ac dc_gain find aol_db at=100
meas ac ugbw when aol_db=0 fall=1
meas ac pm_deg find aol_phase when aol_db=0 fall=1
let pm = 180 + pm_deg
print dc_gain ugbw pm

quit
.endc
.end

